class Money extends ValueObject<{ amount: number; currency: Currency }> {
  constructor(amount: number, currency: Currency) {
    super(ensureValidMoney({ amount, currency }));
  }
  add(other: Money): Money {
    return new Money(this.value.amount + other.value.amount, this.value.currency);
  }
}

class CustomerAccountId extends ValueObject<string> {
  constructor(value: string) { super(ensureValidId(value)); }
}
class BankAccountId extends ValueObject<string> {
  constructor(value: string) { super(ensureValidId(value)); }
}

class CustomerAccountOpened extends DomainEvent<{ accountId: string }> {
  static readonly EVENT_NAME = 'customer.customer-account-opened.v1';
  readonly eventName = CustomerAccountOpened.EVENT_NAME;
  static fromPrimitives(data: EventPrimitives<{ accountId: string }>): CustomerAccountOpened {
    return new CustomerAccountOpened(data.payload, new Date(data.occurredAt));
  }
}
type CustomerAccountEvent = CustomerAccountOpened;

class CustomerAccount extends AggregateRoot<CustomerAccountId, CustomerAccountEvent> {
  private constructor(id: CustomerAccountId, private accounts: BankAccount[]) {
    super(id);
  }

  static create(id: CustomerAccountId, deps: DomainDeps = systemDeps): CustomerAccount {
    const account = new CustomerAccount(id, []);
    account.addDomainEvent(new CustomerAccountOpened({ accountId: id.value }, deps.clock.now()));
    return account;
  }

  static restore(snapshot: CustomerAccountSnapshot): CustomerAccount {
    return new CustomerAccount(
      new CustomerAccountId(snapshot.id),
      snapshot.accounts.map(BankAccount.restore),
    );
  }

  openAccountForCurrency(currency: Currency, deps: DomainDeps = systemDeps): void {
    if (this.accounts.some((a) => a.isForCurrency(currency))) {
      throw new DomainBusinessError('There is already an account for that currency');
    }
    const id = new BankAccountId(deps.idGenerator.generate());
    this.accounts = [...this.accounts, BankAccount.open(id, currency)];
  }

  addMoney(amount: Money): void {
    const currency = amount.value.currency;
    if (!this.accounts.some((a) => a.isForCurrency(currency))) {
      throw new DomainBusinessError('No account for that currency');
    }
    this.accounts = this.accounts.map((a) => (a.isForCurrency(currency) ? a.addMoney(amount) : a));
  }

  toPrimitives(): CustomerAccountSnapshot {
    return { id: this.id.value, accounts: this.accounts.map((a) => a.toPrimitives()) };
  }
}

class BankAccount extends Entity<BankAccountId> {
  private constructor(id: BankAccountId, private readonly currency: Currency, private readonly balance: Money) {
    super(id);
  }
  static open(id: BankAccountId, currency: Currency): BankAccount {
    return new BankAccount(id, currency, new Money(0, currency));
  }
  static restore(snapshot: BankAccountSnapshot): BankAccount {
    const currency = new Currency(snapshot.currency);
    return new BankAccount(new BankAccountId(snapshot.id), currency, new Money(snapshot.balance, currency));
  }
  isForCurrency(c: Currency): boolean { return this.currency.isEqual(c); }
  addMoney(amount: Money): BankAccount { return new BankAccount(this.id, this.currency, this.balance.add(amount)); }
  toPrimitives(): BankAccountSnapshot {
    return { id: this.id.value, currency: this.currency.value, balance: this.balance.value.amount };
  }
}

