class Invoice extends AggregateRoot<InvoiceId, InvoiceEvent> {
  private constructor(id: InvoiceId, private lines: InvoiceLine[], private status: InvoiceStatus) {
    super(id);
  }
  static restore(snapshot: InvoiceSnapshot): Invoice {
    return new Invoice(new InvoiceId(snapshot.id), snapshot.lines.map(InvoiceLine.restore), new InvoiceStatus(snapshot.status));
  }
  addLine(line: InvoiceLine): void {
    if (this.status.isClosed()) throw new DomainBusinessError('Invoice is closed');
    this.lines = [...this.lines, line];
  }
